CREATE TABLE IF NOT EXISTS `one_sgod_iso_qms_records` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`section_name` VARCHAR(255) NOT NULL,`sec_group` VARCHAR(50) NOT NULL DEFAULT 'SGOD',`module` VARCHAR(50) NOT NULL,`username` VARCHAR(255) NOT NULL,`record_date` DATE NOT NULL,`reference_no` VARCHAR(100) NULL,`title` VARCHAR(500) NOT NULL,`details` TEXT NULL,`owner` VARCHAR(255) NULL,`status` VARCHAR(50) NULL,`due_date` DATE NULL,`created_at` DATETIME NOT NULL,`updated_at` DATETIME NULL,PRIMARY KEY(`id`),KEY `idx_section_module` (`section_name`,`sec_group`,`module`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
